def compute(vars):
    expected_berths = vars["v1"]
    current_berths = vars["v2"]

    if current_berths == 0:
        return None

    increase_ratio = expected_berths / current_berths
    percentage_increase = increase_ratio * 100

    return {
        "value": percentage_increase,
        "trace": {
            "expected_berths": expected_berths,
            "current_berths": current_berths,
            "increase_ratio": increase_ratio,
            "output_meta": {
                "currency": None,
                "scale": "percent",
                "unit": "percentage"
            }
        }
    }
